#include <stdio.h>

int main(void) {
    int q, n;
    if (scanf("%d %d", &q, &n) != 2) return 1;
    int con[100], xong[100];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &con[i]) != 1) return 1;
        xong[i] = 0;
    }

    int thoi_gian = 0, conLai = n;
    while (conLai > 0) {
        for (int i = 0; i < n; i++) {
            if (con[i] <= 0) continue;
            int chay = con[i] < q ? con[i] : q;
            thoi_gian += chay;
            con[i] -= chay;
            if (con[i] == 0) {
                xong[i] = thoi_gian;
                conLai--;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%d", xong[i]);
        if (i + 1 < n) printf(" ");
    }
    printf("\n");
    return 0;
}
